#!/usr/bin/env bash
# The parquet files both runs read.
#
#   scripts/arggym/prepare_data.sh
#
# GSM8K hard control: the screened questions (the committed screen under
# data/gsm8k-screen/), dev 200 test rows, seed 0. Downloads openai/gsm8k from the Hub.
#
# ArgGYM: experiment 003's pool, training restricted to its 57 (task, level) cells,
# dev all 96. The pool (data/arggym-pool/pools/0df63cbebe86/) is generated by the
# arggym library from fixed seeds when its train.jsonl (60 MB, not committed) is
# missing: a few minutes on 16 CPU cores (POOL_WORKERS sets the processes). It comes
# out byte-identical to the committed dev.jsonl and summary.json, so `git status`
# shows any difference.
#
# Each output directory gets a manifest.json with the ids; the committed manifests let
# `git diff` show whether the rows changed.
set -euo pipefail
cd "$(dirname "$0")/../.."
export CUDA_VISIBLE_DEVICES=
PY=.venv/bin/python

"$PY" -m arggym_verl.data arggym_verl/tasks/gsm8k-hard.yaml --out data/gsm8k-hard
"$PY" -m arggym_verl.data arggym_verl/tasks/arggym-003.yaml --out data/arggym-qwen3.5-4b \
  ${POOL_WORKERS:+--workers "$POOL_WORKERS"}
